inline double get_awd_diffuse_rgba(std::optional<double> color, std::optional<double> alpha) {
  const double rgb = (color.has_value() ? color.value() : 16777215.0);
  const double alpha_byte = (alpha.has_value() ? flight::maximum(0.0, flight::minimum(255.0, flight::round((alpha.value() * 255.0)))) : 255.0);
  return flight::unsigned_right_shift(flight::bitwise_or(flight::unsigned_right_shift(flight::left_shift(rgb, 8.0), 0.0), alpha_byte), 0.0);
}

inline double get_awd_specular_rgba(std::optional<double> color, double strength) {
  const double rgb = (color.has_value() ? color.value() : flight::scene3d_formats::awd2_material_default_specular_rgb);
  const double scale = flight::maximum(0.0, flight::minimum(1.0, strength));
  const double red = flight::round((flight::bitwise_and(flight::unsigned_right_shift(rgb, 16.0), 255.0) * scale));
  const double green = flight::round((flight::bitwise_and(flight::unsigned_right_shift(rgb, 8.0), 255.0) * scale));
  const double blue = flight::round((flight::bitwise_and(rgb, 255.0) * scale));
  return flight::unsigned_right_shift(flight::bitwise_or(flight::bitwise_or(flight::bitwise_or(flight::left_shift(red, 24.0), flight::left_shift(green, 16.0)), flight::left_shift(blue, 8.0)), 255.0), 0.0);
}


